<?php declare(strict_types=1); $money=static fn(int $v):string=>number_format($v,0,',','.').' ₫'; ?>
<header class="resource-header"><div><span class="booking-eyebrow">Settlement #<?= $settlement->id ?></span><h1><?= htmlspecialchars($settlement->propertyName,ENT_QUOTES,'UTF-8') ?></h1><p>Kỳ <?= $settlement->from ?> → <?= $settlement->to ?> · <?= $settlement->status==='FINALIZED'?'Đã chốt':'Bản nháp' ?></p></div><div class="resource-header__actions"><a class="button button--secondary" href="<?= $baseUrl ?>/partner/settlements/<?= $settlement->id ?>/export">Tải CSV</a><?php if($settlement->status==='DRAFT'):?><form method="post" action="<?= $baseUrl ?>/partner/settlements/<?= $settlement->id ?>/finalize"><input type="hidden" name="_token" value="<?= $csrfToken ?>"><button class="button button--primary" type="submit">Chốt đối soát</button></form><?php endif;?></div></header>
<section class="report-metric-grid settlement-metrics"><article><span>Hóa đơn</span><strong><?= $settlement->bookingCount ?></strong><small>Booking hoàn tất trong snapshot</small></article><article><span>Doanh thu gộp</span><strong><?= $money($settlement->grossRevenue->amount()) ?></strong><small>Online + tại cơ sở</small></article><article><span>Thu trực tuyến</span><strong><?= $money($settlement->onlineCollected->amount()) ?></strong><small>PAY_ONLINE</small></article><article><span>Thu tại cơ sở</span><strong><?= $money($settlement->atPropertyCollected->amount()) ?></strong><small>Tiền mặt/chuyển khoản/thẻ</small></article><article><span>Đã hoàn</span><strong><?= $money($settlement->refunded->amount()) ?></strong><small>Khấu trừ khỏi doanh thu</small></article><article><span>Doanh thu thuần</span><strong><?= $money($settlement->netRevenue->amount()) ?></strong><small>Số đối soát cuối kỳ</small></article></section>
<section class="resource-surface"><header class="resource-card-heading"><h2>Chi tiết hóa đơn</h2><p>Dữ liệu giữ nguyên theo snapshot kỳ đối soát.</p></header><div class="resource-table-wrap"><table class="resource-table"><thead><tr><th>Booking / hóa đơn</th><th>Phát hành</th><th>Hình thức</th><th>Kênh thu</th><th>Tổng</th><th>Hoàn</th><th>Thuần</th></tr></thead><tbody><?php if($settlement->lines===[]):?><tr><td colspan="7" class="empty-cell">Không có hóa đơn trong kỳ này.</td></tr><?php endif;?><?php foreach($settlement->lines as $line):?><tr><td><strong><?= htmlspecialchars((string)$line['bookingCode'],ENT_QUOTES,'UTF-8') ?></strong><small><?= htmlspecialchars((string)$line['invoiceNumber'],ENT_QUOTES,'UTF-8') ?></small></td><td><?= htmlspecialchars((string)$line['issuedAt'],ENT_QUOTES,'UTF-8') ?></td><td><?= $line['paymentTiming']==='PAY_ONLINE'?'Trực tuyến':'Tại cơ sở' ?></td><td><?= htmlspecialchars((string)$line['collectionChannel'],ENT_QUOTES,'UTF-8') ?></td><td><?= $money((int)$line['total']) ?></td><td><?= $money((int)$line['refunded']) ?></td><td><strong><?= $money((int)$line['net']) ?></strong></td></tr><?php endforeach;?></tbody></table></div></section>
